/*
 * A100717  Numbers k having a prime divisor p such that p^p is the highest
 *          power of p that divides k.
 * https://oeis.org/A100717
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   A100717 – numbers k that contain a prime divisor p with exponent
 *            exactly p (that is, p^p is the largest power of p dividing k).
 *            The sequence is generated by scanning integers and retaining
 *            those that satisfy the condition. This implementation uses a
 *            trial‑division sieve up to a fixed bound (suffi...
 * Range:     u8 n <= 37, u16 n <= 9622, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* ------------------------------------------------------------------ */
/* Prime sieve ------------------------------------------------------- */
/* ------------------------------------------------------------------ */

/* Upper bound for the sieve – 1 million primes is plenty for
   the first 10 000 terms (the 10 000th term is < 700 000). */
#define SIEVE_MAX 1000000

/* static storage for the prime table */
static uint32_t primes[SIEVE_MAX + 1];
static size_t prime_count = 0;
static bool primes_sieved = false;

/* Perform the sieve only once. */
static void
ensure_primes(void)
{
    if (primes_sieved)
        return;

    /* False means prime, true means composite. */
    bool is_composite[SIEVE_MAX + 1] = {false};
    primes[0] = 2;
    prime_count = 1;

    for (uint32_t i = 3; i <= SIEVE_MAX; i += 2)
    {
        if (!is_composite[i])
        {
            primes[prime_count++] = i;
            /* Avoid overflow of i*i */
            if ((uint64_t)i * i <= SIEVE_MAX)
            {
                for (uint32_t j = i * i; j <= SIEVE_MAX; j += 2 * i)
                    is_composite[j] = true;
            }
        }
    }
    primes_sieved = true;
}

/* ------------------------------------------------------------------ */
/* Candidate filter --------------------------------------------------- */
/* ------------------------------------------------------------------ */

/* Return true iff n contains a prime factor p whose exponent equals p. */
static bool
candidate_valid(seq_t n)
{
    seq_t m = n;

    for (size_t i = 0; i < prime_count; ++i)
    {
        uint32_t p = primes[i];
        /* Stop when p^2 > m; the remaining m (if >1) is prime. */
        if ((seq_t)p * p > m)
            break;

        if (m % p == 0)
        {
            int exp = 0;
            while (m % p == 0)
            {
                m /= p;
                ++exp;
            }
            if (exp == (int)p)      /* p is small enough for int comparison */
                return true;
        }
    }

    /* Remaining factor (if >1) is prime with exponent 1 – cannot match any p. */
    return false;
}

/* ------------------------------------------------------------------ */
/* Sequence storage --------------------------------------------------- */
/* ------------------------------------------------------------------ */

static seq_t *terms = NULL;      /* dynamic array of terms */
static size_t terms_cap = 0;     /* current capacity */
static size_t terms_len = 0;     /* number of stored terms */
static seq_t candidate = 1;      /* last tested integer */

/* Append a term to the dynamic array, growing it if necessary. */
static void
push_term(seq_t val)
{
    if (terms_len == terms_cap)
    {
        size_t new_cap = terms_cap ? terms_cap * 2 : 16;
        seq_t *tmp = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
        if (!tmp)
            abort();               /* allocation failure */
        terms = tmp;
        terms_cap = new_cap;
    }
    terms[terms_len++] = val;
}

/* Ensure that at least n terms have been computed. */
static void
ensure_terms(idx_t n)
{
    if (n == 0)
        return;

    ensure_primes();

    while (terms_len < (size_t)n)
    {
        ++candidate;
        if (candidate_valid(candidate))
            push_term(candidate);
    }
}

/* ------------------------------------------------------------------ */
/* Sequence function ------------------------------------------------- */
/* ------------------------------------------------------------------ */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;        /* out of range; callers are responsible */
    ensure_terms(n);
    return terms[n - 1];
}
